"use client";

import { useState } from "react";
import dynamic from "next/dynamic";
import { Loader2, Plus } from "lucide-react";

// 👇 Importação dinâmica: só carrega no navegador (Client-Side)
const PluggyConnect = dynamic(
  () => import("react-pluggy-connect").then((mod) => mod.PluggyConnect),
  { ssr: false }
);

export function PluggyConnectButton() {
  const [connectToken, setConnectToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleOpenWidget = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/pluggy/connect-token", { method: "POST" });
      const data = await res.json();
      
      if (!res.ok) throw new Error(data.error);
      
      setConnectToken(data.accessToken);
    } catch (error) {
      console.error("Erro ao abrir widget:", error);
      alert("Erro ao conectar com o banco.");
    } finally {
      setIsLoading(false);
    }
  };

  const onSuccess = async (itemData: any) => {
    console.log("Sucesso! Item ID:", itemData.item.id);
    setConnectToken(null);

    try {
      const res = await fetch("/api/pluggy/sync", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ itemId: itemData.item.id }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Erro na sincronização");

      alert("Contas e transações sincronizadas com sucesso!");
      window.location.reload(); 
    } catch (error: any) {
      console.error("Erro na sincronização:", error);
      alert("Conexão salva, mas houve um erro ao sincronizar os dados. Tente novamente.");
    }
  };

  const onError = (error: any) => {
    console.error("Erro na conexão:", error);
    setConnectToken(null);
  };

  return (
    <>
      <button 
        onClick={handleOpenWidget}
        disabled={isLoading}
        className="flex items-center justify-center gap-2 rounded-xl bg-fuchsia-600 px-4 py-2 text-sm font-semibold text-white transition-all hover:bg-fuchsia-500 disabled:opacity-70"
      >
        {isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : <Plus className="h-5 w-5" />}
        Conectar Banco (Open Finance)
      </button>

      {connectToken && (
        <PluggyConnect
          connectToken={connectToken}
          onSuccess={onSuccess}
          onError={onError}
          includeSandbox={true} 
        />
      )}
    </>
  );
}